async function productionAction(action,cid){
 const svc=P();if(!svc)return alert("Service de mise en service indisponible.");
 const title=moduleTitle(cid,cid);
 if(action==="promote"){
   const check=svc.canPromote(cid);
   if(!check?.ok)return alert("Mise en service impossible : "+(check?.reason||"état invalide"));
   if(!confirm(`METTRE EN SERVICE SUR TOUS LES POSTES\n\nModule : ${title}\n\nLa version testée et validée sera utilisée au prochain chargement de Koha sur chaque poste. La version précédente reste disponible pour un retour arrière.\n\nContinuer ?`))return;
   const r=await svc.promote(cid);
   if(!r?.ok)return alert("Mise en service impossible : "+(r?.reason||r?.error||"erreur"));
   alert("Mise en service enregistrée. La page va être rechargée avec la version validée.");
   location.reload();return;
 }
 if(action==="rollback"){
   if(!confirm(`REVENIR À LA VERSION PRÉCÉDENTE\n\nModule : ${title}\n\nLa version précédente sera de nouveau utilisée au prochain chargement sur les postes concernés.\n\nContinuer ?`))return;
   const r=await svc.rollback(cid);
   if(!r?.ok)return alert("Retour impossible : "+(r?.reason||r?.error||"erreur"));
   alert("Retour enregistré. La page va être rechargée avec la version précédente.");
   location.reload();
 }
}
