 function availableTabs(){const tabs=[["features","Réglages","current"]];if(appearanceKeys().length)tabs.push(["appearance","Apparence","current"]);if(configAdminMode)tabs.push(["advanced","Avancé","advanced"]);if(configAdminMode&&A()?.can?.("developer"))tabs.push(["json","JSON","advanced"]);return tabs}
