   modal.querySelectorAll("[data-array-remove]").forEach(b=>b.onclick=e=>{e.preventDefault();syncEditorInputs(modal,cfg);pathDel(cfg,JSON.parse(b.dataset.arrayRemove));markDirty();draw()});
   modal.querySelectorAll("[data-array-add]").forEach(b=>b.onclick=()=>{syncEditorInputs(modal,cfg);const path=JSON.parse(b.dataset.arrayAdd),arr=pathGet(cfg,path)||[],baseArr=pathGet(base,path)||[];if((arr[0]&&typeof arr[0]==="object")||(baseArr[0]&&typeof baseArr[0]==="object")){const tpl=clone(baseArr[0]||arr[0]||{});Object.keys(tpl).forEach(k=>{if(typeof tpl[k]==="string")tpl[k]=""});arr.push(tpl)}else arr.push("");pathSet(cfg,path,arr);markDirty();draw()});
   modal.querySelectorAll("[data-matrix-add-row]").forEach(b=>b.onclick=()=>{syncEditorInputs(modal,cfg);const path=JSON.parse(b.dataset.matrixAddRow),arr=pathGet(cfg,path)||[],cols=Math.max(1,...arr.map(r=>Array.isArray(r)?r.length:0));arr.push(Array(cols).fill(""));pathSet(cfg,path,arr);markDirty();draw()});
