   modal.querySelectorAll("[data-matrix-remove-col]").forEach(b=>b.onclick=()=>{syncEditorInputs(modal,cfg);const path=JSON.parse(b.dataset.matrixRemoveCol),arr=pathGet(cfg,path)||[];arr.forEach(r=>{if(Array.isArray(r)&&r.length>1)r.pop()});pathSet(cfg,path,arr);markDirty();draw()});
   modal.querySelectorAll("[data-matrix-remove-row]").forEach(b=>b.onclick=()=>{syncEditorInputs(modal,cfg);const path=JSON.parse(b.dataset.matrixRemoveRow),arr=pathGet(cfg,path)||[],i=Number(b.dataset.row);arr.splice(i,1);pathSet(cfg,path,arr);markDirty();draw()});
