 modal.querySelector("[data-config-search]").addEventListener("input",applyFilters);modal.querySelector("[data-only-changed]").addEventListener("change",applyFilters);
 const moduleEnabled=modal.querySelector("[data-module-enabled]");if(moduleEnabled)moduleEnabled.onchange=()=>{cfg.enabled=moduleEnabled.checked;const label=moduleEnabled.closest(".pmk-main-toggle")?.querySelector("span");if(label)label.textContent=moduleEnabled.checked?"Activé":"Désactivé";markDirty()};
 const recipeButton=modal.querySelector("[data-cfg-recipe]");if(recipeButton)recipeButton.onclick=()=>{if(dirty&&!confirm("Des modifications ne sont pas enregistrées. Ouvrir quand même les tests ?"))return;modal.remove();activeTab="recipe";render()};
 modal.querySelector("[data-cfg-close]").onclick=()=>{if(dirty&&!confirm("Fermer sans enregistrer les modifications ?"))return;document.getElementById("ktm-css-preview")?.remove();modal.remove()};
 modal.querySelector("[data-cfg-reset-all]").onclick=()=>{if(!confirm("Rétablir toute la configuration de ce module aux valeurs par défaut ?"))return;Object.keys(cfg).forEach(k=>delete cfg[k]);Object.assign(cfg,clone(base));markDirty();draw()};
