 const saveLocalBtn=modal.querySelector("[data-cfg-save-local]");if(saveLocalBtn)saveLocalBtn.onclick=()=>{if(!absorb())return;if(cfg.appearance){if(typeof cfg.appearance.defaultCss==="string")cfg.appearance.defaultCss=normalizeCssText(cfg.appearance.defaultCss);if(typeof cfg.appearance.customCss==="string")cfg.appearance.customCss=normalizeCssText(cfg.appearance.customCss)}KT.Config.setCanonicalLocalOverride(cid,cfg);document.getElementById("ktm-css-preview")?.remove();modal.remove();render();alert("Réglages enregistrés uniquement dans ce navigateur. Les autres postes ne sont pas modifiés.")};
